import socket, struct
def axfr(zone, server="127.0.0.11"):
    # build AXFR query (TCP)
    tid=b'\xab\xcd'; flags=b'\x00\x00'; qd=struct.pack('>H',1); an=ns=ar=struct.pack('>H',0)
    q=b''.join(bytes([len(p)])+p.encode() for p in zone.split('.'))+b'\x00'+struct.pack('>HH',252,1)
    msg=tid+flags+qd+an+ns+ar+q
    s=socket.create_connection((server,53),timeout=5)
    try:
        s.send(struct.pack('>H',len(msg))+msg)
        data=s.recv(65535)
        # parse rcode
        rcode=data[3]&0xf
        print(zone, "rcode", rcode, "len", len(data))
        return data
    finally: s.close()
for z in ["internal","local","internal.local","docker",""]:
    try:
        d=axfr(z) if z else None
